mapper.select:
SELECT name, value, 0 AS compare
FROM (
    SELECT '收' AS name, NVL(SUM(payment_amount), 0) AS value, 1 AS ord FROM tr_settle_payments
    WHERE stat_date BETWEEN #{startDate} AND #{endDate} AND money_type = #{moneyType}
    UNION ALL
    SELECT '退' AS name, NVL(SUM(refunded_amount), 0) AS value, 2 AS ord FROM tr_settle_payments
    WHERE stat_date BETWEEN #{startDate} AND #{endDate} AND money_type = #{moneyType}
)
ORDER BY ord
